
# Create four charts from the saved ML model results.

import pandas as pd
import matplotlib.pyplot as plt

from config import Config


# Read a CSV file.
def read_csv(path):
    if path.exists():
        return pd.read_csv(path)
    return pd.DataFrame()


# Save a chart as an image.
def save_chart(folder, filename):
    plt.tight_layout()
    plt.savefig(folder / filename, dpi=140)
    plt.close()
    print("Saved:", folder / filename)


# 1. Actual Sales vs Predicted Sales
def prediction_chart(config, folder):

    # Read the predictions generated by the ML pipeline.
    path = config.results / "predictions" / "spark_test_predictions.csv"

    if not path.exists():
        path = config.results / "predictions" / "test_predictions.csv"

    df = read_csv(path)

    if df.empty or "sales" not in df.columns:
        print("Prediction data not found.")
        return

    # Find prediction columns available in the file.
    columns = [
        c for c in ["gbr_prediction", "gbt_prediction",
                     "rf_prediction", "dt_prediction",
                     "prediction"]
        if c in df.columns
    ]
    
    if not columns:
        print("No prediction columns found.")
        return

    # Use dates if available; otherwise use row numbers.
    x = df["date"] if "date" in df.columns else range(len(df))

    # Draw actual sales and predicted sales.
    plt.figure(figsize=(9, 4))
    plt.plot(x, df["sales"], label="Actual Sales")

    for col in columns:
        plt.plot(x, df[col], label=col)

    plt.title("Actual vs Predicted Sales")
    plt.xlabel("Date or Record")
    plt.ylabel("Units Sold")
    plt.legend()
    save_chart(folder, "actual_vs_predicted.png")


# 2. Model Performance
def performance_chart(config, folder):

    # Read the evaluation metrics calculated by the models.
    path = config.results / "metrics" / "spark_model_metrics.csv"

    if not path.exists():
        path = config.results / "metrics" / "model_metrics.csv"

    df = read_csv(path)

    if df.empty or "model" not in df.columns:
        print("Model metrics not found.")
        return

    # Compare the error metrics available in the file.
    metrics = [c for c in ["mae", "rmse", "wape"] if c in df.columns]

    if not metrics:
        print("No supported metrics found.")
        return

    # Draw a bar chart comparing the models.
    df.set_index("model")[metrics].plot(kind="bar", figsize=(9, 4))
    plt.title("Model Performance Comparison")
    plt.ylabel("Error (lower is better)")
    plt.xticks(rotation=20)

    save_chart(folder, "model_performance.png")


# 3. Model Prediction Residuals
def residual_chart(config, folder):

    # Read actual sales and model predictions.
    path = config.results / "predictions" / "spark_test_predictions.csv"

    if not path.exists():
        path = config.results / "predictions" / "test_predictions.csv"

    df = read_csv(path)

    if df.empty or "sales" not in df.columns:
        print("Prediction data not found for residuals.")
        return

    # Residual = actual sales minus predicted sales.
    models = {
        "GBT": "gbt_prediction",
        "RF": "rf_prediction",
        "DT": "dt_prediction"
    }

    plt.figure(figsize=(9, 4))
    plotted = False

    for name, col in models.items():
        if col in df.columns:
            residual = df["sales"] - df[col]
            plt.plot(residual.values, label=name, marker=".", markersize=3)
            plotted = True

    if not plotted:
        print("No matching prediction columns for residuals.")
        plt.close()
        return

    # Zero means actual sales matched the prediction.
    plt.axhline(0, linestyle="--")
    plt.title("Model Prediction Residuals")
    plt.xlabel("Test Record")
    plt.ylabel("Actual - Predicted")
    plt.legend()

    save_chart(folder, "model_residuals.png")


# 4. Forecast Error Across 1–7 Days
def horizon_chart(config, folder):

    # Read previously calculated multi-day forecast metrics.
    path = config.results / "metrics" / "horizon_metrics.csv"

    if not path.exists():
        path = config.results / "metrics" / "forecast_horizon_metrics.csv"

    df = read_csv(path)

    if df.empty or "horizon" not in df.columns:
        print("Horizon metrics not found; chart skipped.")
        return

    # Draw whichever WAPE columns are available.
    columns = [
        c for c in ["rf_wape", "ma_wape", "naive_wape", "gbt_wape"]
        if c in df.columns
    ]

    if not columns:
        print("No horizon WAPE columns found.")
        return

    df = df.sort_values("horizon")

    plt.figure(figsize=(9, 4))

    for col in columns:
        plt.plot(df["horizon"], df[col], marker="o", label=col)

    plt.title("Forecast Error Across 1–7 Day Horizons")
    plt.xlabel("Forecast Horizon")
    plt.ylabel("WAPE")
    plt.legend()

    save_chart(folder, "forecast_horizon_metrics.png")


# Run all four chart functions.
def generate_spark_charts():

    config = Config()
    config.prepare()

    # Save all charts in the results/charts folder.
    folder = config.results / "charts"
    folder.mkdir(parents=True, exist_ok=True)

    prediction_chart(config, folder)
    performance_chart(config, folder)
    residual_chart(config, folder)
    horizon_chart(config, folder)

    print("Chart generation finished.")


if __name__ == "__main__":
    generate_spark_charts()
